import React, { useState } from "react";
import Inline from "../Inline";
import Stack from "../Stack";
import Checkbox from "./";
import CheckboxGroup from "../CheckboxGroup";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Checkbox> = {
  id: "Components/Checkbox",
  title: "Components/Checkbox/Checkbox",
  component: Checkbox,
  args: {
    label: "Label",
    size: "medium",
  },
  argTypes: {
    checked: {
      type: "boolean",
      description: "Controls whether the checkbox is checked",
    },
    disabled: {
      type: "boolean",
      description: "Controls whether the checkbox is disabled",
    },
    size: {
      options: ["medium", "large"],
      control: "radio",
      description: "The size of the checkbox",
    },
  },
};

export default meta;
type Story = StoryObj<typeof Checkbox>;

export const Basic: Story = {
  tags: ["visual-test"],
  render: (args) => {
    return <Checkbox {...args} defaultChecked={args.checked} />;
  },
};

export const Disabled: Story = {
  args: {
    disabled: true,
  },
  render: (args) => {
    return (
      <Inline spacing="2-x">
        <Checkbox {...args} label="Label" defaultChecked />
        <Checkbox {...args} label="Label" />
      </Inline>
    );
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  ...Disabled,
  args: { disabled: false },
  decorators: [withDarkMode],
};

export const Size: Story = {
  render: () => {
    return (
      <Inline spacing="2-x">
        <Checkbox label="Large" defaultChecked size="large" />
        <Checkbox label="Medium (default)" defaultChecked />
      </Inline>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [options, setOptions] = useState({ option1: true, option2: false });
    return (
      <Inline spacing="2-x">
        <Checkbox
          label="Option A"
          checked={options.option1}
          onChange={(_, checked: boolean) =>
            setOptions({ ...options, option1: checked })
          }
        />
        <Checkbox
          label="Option B"
          checked={options.option2}
          onChange={(_, checked: boolean) =>
            setOptions({ ...options, option2: checked })
          }
        />
      </Inline>
    );
  },
};

export const Intermediate: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const OPTIONS = ["a", "b", "c", "d"];
    const [selected, setSelected] = useState(["b"]);

    return (
      <Stack spacing="1-x">
        <Checkbox
          label="Select all"
          checked={selected.length === OPTIONS.length}
          indeterminate={
            selected.length > 0 && selected.length < OPTIONS.length
          }
          onChange={(_: any, checked: boolean) => {
            setSelected(checked ? OPTIONS : []);
          }}
        />
        <CheckboxGroup
          value={selected}
          onChange={(_, value) => setSelected(value)}
          style={{ paddingLeft: "2rem" }}
        >
          {OPTIONS.map((optionValue) => (
            <Checkbox
              key={optionValue}
              label={`Option ${optionValue.toUpperCase()}`}
              value={optionValue}
            />
          ))}
        </CheckboxGroup>
      </Stack>
    );
  },
};
